import {rubberHoseRig,updateRubberHose} from '../scene/rubberhose.js';
import {enableTrack} from '../animation/evaluate.js';
export function rubberHoseControls(n,time){if(!n.rubberhose)return '';const r=rubberHoseRig(n,time),disabled=r.enabled?'':'disabled';return `<section class="prop-section"><h3 class="prop-title">Limb rig · simple IK</h3><label class="properties-check"><input data-hose="ik" type="checkbox" ${r.enabled?'checked':''}> Solve bend when endpoints move</label><div class="prop-grid"><label>Upper length (px)<input data-hose="length1" type="number" min=".001" max="1000000" step="1" value="${r.length1.toFixed(2)}" ${disabled}></label><label>Lower length (px)<input data-hose="length2" type="number" min=".001" max="1000000" step="1" value="${r.length2.toFixed(2)}" ${disabled}></label><label>Bend side<select data-hose="direction" ${disabled}><option value="1" ${r.direction>0?'selected':''}>Clockwise</option><option value="-1" ${r.direction<0?'selected':''}>Counterclockwise</option></select></label></div><label class="properties-check"><input data-hose="stretch" type="checkbox" ${r.stretch?'checked':''} ${disabled}> Stretch beyond reach</label><p class="subtle">${r.enabled?'Direct select: drag the first or last point to pose the limb. Drag the middle point across the limb to flip its bend. Length and side changes add a path key at the playhead.':'Free curve: drag all three points independently. Enable IK to preserve the current segment lengths.'}</p></section>`;}
export function applyRubberHoseControl(a,n,key,value){if(!n.rubberhose||!['ik','stretch','length1','length2','direction'].includes(key))return false;const changes={[key]:value};a.pause();a.properties?.flush();a.history.run('Edit limb rig',()=>{if(['length1','length2','direction'].includes(key)||key==='ik'&&value)enableTrack(n,'nodes',a.time,a.ease);updateRubberHose(n,changes,a.time);});a.render();return true;}
